wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` is a precondition the caller
        // guarantees; it holds of every input, so the body does not re-check it.

        let system = "You are a customer-support agent. Answer the user's \
            question using the provided context. You may call the `lookup` tool \
            to search the knowledge base when you need more information.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');
        if !ctx.knowledge.is_empty() {
            prompt.push_str("Known context:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop. The only tool in scope is `lookup`,
        // backed by the read-only knowledge-base handle.
        const MAX_ROUNDS: usize = 8;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // The node holds no handle for any other tool.
                        prompt.push_str("\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available. Answer using the \
                            knowledge base or what you already know.\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the round limit"
                .to_string(),
        })
    }
}

export!(Node);
```

